import 'package:flutter/material.dart';import 'home_screen.dart';import 'transactions_screen.dart';import 'budgets_screen.dart';import 'reports_screen.dart';import 'more_screen.dart';import 'add_transaction_screen.dart';
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int tab=0,refresh=0;void changed()=>setState(()=>refresh++);@override Widget build(BuildContext context){final pages=[HomeScreen(key:ValueKey('h$refresh'),onAdd:_add,onSeeAll:()=>setState(()=>tab=1)),TransactionsScreen(key:ValueKey('t$refresh'),onChanged:changed),BudgetsScreen(key:ValueKey('b$refresh'),onChanged:changed),ReportsScreen(key:ValueKey('r$refresh')),MoreScreen(onChanged:changed)];return Scaffold(body:IndexedStack(index:tab,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'Activity'),NavigationDestination(icon:Icon(Icons.pie_chart_outline),label:'Budgets'),NavigationDestination(icon:Icon(Icons.bar_chart),label:'Reports'),NavigationDestination(icon:Icon(Icons.apps),label:'More') ]));}Future<void> _add()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>AddTransactionScreen(onSaved:changed)));changed();}}
